CREATE OR REPLACE FUNCTION public.staff_update_notification_preferences(p_master boolean,p_offers boolean,p_jobs boolean,p_schedule boolean,p_system boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path = '' AS $$ declare u uuid := auth.uid(); begin if u is null then raise exception using errcode='42501',message='Oturum gerekli'; end if; insert into public.staff_notification_preferences(user_id,enabled,offers,jobs,schedule,system,updated_at) values(u,p_master,p_offers,p_jobs,p_schedule,p_system,now()) on conflict(user_id) do update set enabled=excluded.enabled,offers=excluded.offers,jobs=excluded.jobs,schedule=excluded.schedule,system=excluded.system,updated_at=now(); return jsonb_build_object('user_id',u,'master',p_master,'offers',p_offers,'jobs',p_jobs,'schedule',p_schedule,'system',p_system); end; $$;
REVOKE ALL ON FUNCTION public.staff_update_notification_preferences(boolean,boolean,boolean,boolean,boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.staff_update_notification_preferences(boolean,boolean,boolean,boolean,boolean) FROM anon;
GRANT EXECUTE ON FUNCTION public.staff_update_notification_preferences(boolean,boolean,boolean,boolean,boolean) TO authenticated;
